#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    int top;
    int capacity;
} Stack;

Stack* createStack(int cap) {
    Stack *s = (Stack*)malloc(sizeof(Stack));
    s->capacity = cap;
    s->top = -1;
    s->data = (int*)malloc(cap * sizeof(int));
    return s;
}

void push(Stack *s, int val) {
    if (s->top == s->capacity - 1) {
        s->capacity *= 2;
        s->data = (int*)realloc(s->data, s->capacity * sizeof(int));
        printf("[Resized stack to capacity %d]\n", s->capacity);
    }
    s->data[++(s->top)] = val;
}

int pop(Stack *s) {
    if (s->top == -1) {
        printf("Stack Underflow!\n");
        return -1;
    }
    return s->data[(s->top)--];
}

int main() {
    Stack *s = createStack(2);
    push(s, 10); push(s, 20); push(s, 30); // Triggers dynamic resize
    printf("Popped: %d\n", pop(s)); // 30
    printf("Popped: %d\n", pop(s)); // 20
    free(s->data); free(s);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
#include <stdlib.h>

int evalPostfix(char *exp) {
    int stack[100], top = -1;
    for (int i = 0; exp[i] != '\0'; i++) {
        if (isdigit(exp[i])) {
            stack[++top] = exp[i] - '0';
        } else {
            int op2 = stack[top--];
            int op1 = stack[top--];
            switch (exp[i]) {
                case '+': stack[++top] = op1 + op2; break;
                case '-': stack[++top] = op1 - op2; break;
                case '*': stack[++top] = op1 * op2; break;
                case '/': stack[++top] = op1 / op2; break;
            }
        }
    }
    return stack[top];
}

int main() {
    char exp[] = "53+82-*4/"; // ((5+3) * (8-2)) / 4 = (8 * 6) / 4 = 12
    printf("Postfix '%s' evaluates to: %d\n", exp, evalPostfix(exp));
    return 0;
}

#include <stdio.h>
#define MAX 5

int cq[MAX], front = -1, rear = -1;

void enqueue(int val) {
    if ((rear + 1) % MAX == front) {
        printf("Queue is FULL!\n");
        return;
    }
    if (front == -1) front = rear = 0;
    else rear = (rear + 1) % MAX;
    cq[rear] = val;
}

int dequeue() {
    if (front == -1) {
        printf("Queue is EMPTY!\n");
        return -1;
    }
    int item = cq[front];
    if (front == rear) front = rear = -1; // Reset when empty
    else front = (front + 1) % MAX;
    return item;
}

int main() {
    enqueue(10); enqueue(20); enqueue(30);
    printf("Dequeued: %d\n", dequeue()); // 10
    enqueue(40); enqueue(50); enqueue(60); // Wraps around
    printf("Dequeued: %d\n", dequeue()); // 20
    return 0;
}

examModelAnswers.stepByStepAnswer:
1. Disadvantage of Linear Queue:
In a linear queue, when elements are deleted, `front` advances forward. Once `rear == MAX - 1`, subsequent insertions report 'Queue Full' even if spaces are empty at indices before `front`. This false overflow wastes memory.

2. Circular Queue Solution:
Wraps the array in a circular loop using modulo `% MAX`.
• Insert (Enqueue):
```c
if ((rear + 1) % MAX == front) { printf("Overflow"); return; }
if (front == -1) front = rear = 0;
else rear = (rear + 1) % MAX;
q[rear] = val;
```
• Delete (Dequeue):
```c
if (front == -1) { printf("Underflow"); return -1; }
val = q[front];
if (front == rear) front = rear = -1;
else front = (front + 1) % MAX;
return val;
```

