typedef struct BSTNode {
    int data;
    struct BSTNode *left, *right;
} BSTNode;

BSTNode* insert(BSTNode *root, int val) {
    if (root == NULL) {
        BSTNode *node = (BSTNode*)malloc(sizeof(BSTNode));
        node->data = val; node->left = node->right = NULL;
        return node;
    }
