#include <stdio.h>
#define SIZE 7
#define EMPTY -1

int table[SIZE];

void insert(int key) {
    int index = key % SIZE;
    int i = 0;
    while (table[(index + i) % SIZE] != EMPTY && i < SIZE) {
        i++; // Linear probing to next slot
    }
    if (i == SIZE) {
        printf("Hash table is full!\n");
        return;
    }
    table[(index + i) % SIZE] = key;
}

int main() {
    for (int i = 0; i < SIZE; i++) table[i] = EMPTY;
    insert(10); // 10 % 7 = 3
    insert(17); // 17 % 7 = 3 -> collision! Placed at index 4
    insert(24); // 24 % 7 = 3 -> collision! Placed at index 5
    for (int i = 0; i < SIZE; i++) printf("Slot %d: %d\n", i, table[i]);
    return 0;
}

#include <stdio.h>

void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1, n2 = r - m;
    int L[50], R[50];
    for (int i = 0; i < n1; i++) L[i] = arr[l + i];
    for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j];
    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) arr[k++] = L[i++];
        else arr[k++] = R[j++];
    }
    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

int main() {
    int arr[] = {38, 27, 43, 3, 9, 82, 10};
    mergeSort(arr, 0, 6);
    printf("Sorted: ");
    for (int i = 0; i < 7; i++) printf("%d ", arr[i]);
    printf("\n");
    return 0;
}

