#include <stdio.h>
#include <ctype.h>
#include <stdlib.h>

int evalPostfix(char *exp) {
    int stack[100], top = -1;
    for (int i = 0; exp[i] != '\0'; i++) {
        if (isdigit(exp[i])) {
            stack[++top] = exp[i] - '0';
        } else {
            int op2 = stack[top--];
            int op1 = stack[top--];
            switch (exp[i]) {
                case '+': stack[++top] = op1 + op2; break;
                case '-': stack[++top] = op1 - op2; break;
                case '*': stack[++top] = op1 * op2; break;
                case '/': stack[++top] = op1 / op2; break;
            }
        }
    }
    return stack[top];
}

int main() {
    char exp[] = "53+82-*4/"; // ((5+3) * (8-2)) / 4 = (8 * 6) / 4 = 12
    printf("Postfix '%s' evaluates to: %d\n", exp, evalPostfix(exp));
    return 0;
}

